"""Generate a small unapplied local-join proposal from bounded source evidence."""
from pathlib import Path
import argparse,hashlib,json,math
HERE=Path(__file__).resolve().parent

def sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()
def read(name):return json.loads((HERE/name).read_text(encoding='utf-8'))
def build():
 review=read('review-evidence.json');native=read('native-contact-results.json')
 assert native['reviewEvidenceSha256']==sha(HERE/'review-evidence.json')
 pairs={e['case']:e for e in review['targetPairEvidence']};contacts={e['case']:e for e in native['controls']}
 choices=[
  ('portal-jamb-to-floor','fixed-embed','One fixed portal frame; footer attaches to the actual deck, independent of leaf pose.'),
  ('portal-right-jamb-to-floor','fixed-embed','Other actual fixed jamb of the same portal; no widened opening or altered leaf.'),
  ('portal-header-to-fixed-jamb','fixed-embed','Fixed header attaches to the actual left fixed jamb, not an incidental closed-leaf bearing.'),
  ('portal-header-to-right-fixed-jamb','fixed-embed','Fixed header attaches to the actual right fixed jamb.'),
  ('window-jamb-to-wall','fixed-embed','Frame remains parent-dependent. Use its measured overlap with the real wall; glass is not a brace.'),
  ('cornice-to-wall','fixed-embed','One local 1 m wall/cornice fixture. The complete 48 m span requires its actual full local support set before rollout.'),
  ('clerestory-base-to-existing-cornice','fixed-embed','The second-largest component already overlaps its rooted cornice. Add only this exact local dependent join; preserve the original inverse embed evidence.'),
  ('sloped-handrail-to-interior-post','fixed-embed','The rail overlaps this actual intermediate post. Its separated endpoint does not require an inferred mount when this real support is available.'),
  ('closure-cap-to-actual-deck','verified-source-contact-candidate','Both are structural under the proposed classifier. Exact native triangle contact is absent from original broadphase adjacency; add only this named search pair for validation.'),
  ('cap-to-parent-pier','explicit-carpentry-face-joint-proposal','Near-coincident vertical butt faces. Actual contact alone is not horizontal bearing; explicit local timber fastening needs authority and an agreed schema.')
 ]
 proposed=[]
 for name,kind,reason in choices:
  e=pairs[name];n=contacts[name];assert n['nativeContact'] and not e['geometricGapProven']
  if kind=='fixed-embed':assert e['positiveVolumeProof']
  if kind=='verified-source-contact-candidate':assert not e['positiveVolumeProof']
  child_point=e['commonStrictInteriorWitness'] or e['actualSurfaceWitness'][0]
  parent_point=e['commonStrictInteriorWitness'] or e['actualSurfaceWitness'][1]
  def region(which,point):
   return {'frame':'emitted-world','bounds':e['overlapSelectorBounds'] or {'min':point,'max':point},'geometryRefs':e[which+'GeometryRefs'],'witnessPoint':point,'meaning':'Finite selector and witness only; actual source triangles remain authoritative.'}
  proposed.append({'case':name,'proposedKind':kind,'childCarrierId':e['source'],'parentCarrierId':e['candidate'],'direction':'symmetric local structural contact only' if kind=='verified-source-contact-candidate' else 'parent to child dependency only','childRegion':region('source',child_point),'parentRegion':region('candidate',parent_point),'positiveVolumeProof':e['positiveVolumeProof'],'nativeTriangleContact':True,'reason':reason,'wholeCarrierRetirement':False,'groundAnchor':False,'accepted':False,'applied':False})
 gaps=[]
 for name in ['parapet-base-to-roof','parapet-base-to-rooted-cornice']:
  e=pairs[name];assert e['geometricGapProven'] and not contacts[name]['nativeContact']
  gaps.append({'case':name,'childCarrierId':e['source'],'candidateParentCarrierId':e['candidate'],'separationLowerBoundMetres':e['separatingProjectionGapLowerBoundMetres'],'vertexToTriangleUpperBoundMetres':e['closestVertexToTriangleUpperBoundMetres'],'actualSurfaceWitness':e['actualSurfaceWitness'],'witnessSeparationMetres':math.dist(*e['actualSurfaceWitness']),'interpretation':'Genuine separated solids for this exact pair; bounds overlap is not contact. The upper witness separation is not the minimum gap.','nextDecision':'Design decision remains open for this same parapet base: a specific engineered fastening or other authored support needs authority. These are pairwise bounds and two alternative parents, not two independent defects or a global nearest-parent proof. Preserve the actual gap and local patch semantics.','mountApplied':False,'mountAuthorized':False,'geometryChangeAuthorized':False})
 return {'version':1,'status':'UNACCEPTED_PROPOSAL','placeId':'new-york','coordinateConvention':'Carrier IDs are place-local, qualify with new-york:: once. Geometry/matrices and all witnesses are emitted-world; [56,0,26] is already applied.','scope':'Ten exact local control pairs only; eight volume embeds, one structural seam candidate and one carpentry face joint. Not a 1092-ID correction or a production-complete support table.','inputEvidence':[{'path':'art/source/shared-map-fire-bindings/reachability-review-v1/'+p,'sha256':sha(HERE/p)} for p in ['review-evidence.json','native-contact-results.json','propose.py']],'preservedArtCommit':'90c226f674d51a2d030fcdd4679e61a3bdd9ebfe','completedBindingsSha256':review['inputs']['bindings']['sha256'],'diagnosticInterpretationAccepted':False,'classificationFindings':{'existingParentRecordsOmitted':0,'nativeHingeOrHardwareLinksOmitted':0,'coarseRoleCaution':'timber-fitting includes column subparts, rails, cornices and ornaments; one role string is not a load-bearing classification. No blanket role promotion is proposed.','existingContactSearchCaution':'The source exporter records coplanar finite-area faces; the proposed runtime contact compiler searches only recorded adjacency and structural/structural pairs. This can omit actual embedded or shared-cut contacts without any lost source geometry.','attachmentDirectionCaution':'A rooted rail/glass may have an original parent inside an unrooted frame component. Preserve parent-dependent glass/ornament semantics and choose exact real fixed-frame joins; do not globally reverse attachments.'},'proposedLocalPairs':proposed,'portalNormalizationProposal':{'portalId':'ny-front','fixedHeaderCarrierId':'carrier/ny-front/header','originalClosedPoseBearings':[{'childCarrierId':'carrier/ny-front/header','parentCarrierId':'carrier/ny-front/leaf--1','kind':'coplanar-horizontal-triangle-contact'},{'childCarrierId':'carrier/ny-front/header','parentCarrierId':'carrier/ny-front/leaf-1','kind':'coplanar-horizontal-triangle-contact'}],'proposal':'Retain these historical observed contacts, but use the two proposed fixed-jamb joins as permanent fixed-header support. Keep existing jamb-to-leaf hinges and leaf-to-hardware links unchanged.','importantObservation':'Native geometry contacts are true for the measured left leaf in both closed and open poses. Contact existence alone does not establish intended permanent support ownership.','applied':False},'genuineGapCasesHeldForDecision':gaps,'separatedEndpointWithExistingAlternativeContact':{'case':'sloped-handrail-to-post','gapLowerBoundMetres':pairs['sloped-handrail-to-post']['separatingProjectionGapLowerBoundMetres'],'gapUpperBoundMetres':pairs['sloped-handrail-to-post']['closestVertexToTriangleUpperBoundMetres'],'actualEndpointWitness':pairs['sloped-handrail-to-post']['actualSurfaceWitness'],'alternativeCase':'sloped-handrail-to-interior-post','alternativePositiveOverlapProof':pairs['sloped-handrail-to-interior-post']['positiveVolumeProof'],'mountProposed':False,'reason':'An actual local support exists elsewhere on this same rail; the endpoint gap alone is not a reason to add a mount.'},'existingUrnBearingRecommendation':'Keep the exact existing local cap/pier bearing records. Review the parent chain; do not attach urns directly to remote primary walls or ground.','proposedAcceptanceControls':['Validate one static portal with fixed-header support independent of each moving leaf; retire local jamb parents to verify the actual dependent leaf/hardware chain.','Retire the named local wall patch to test its window/cornice dependency; preserve unrelated patches and the original finite stock.','Verify the named cap/deck seam with the unchanged triangle test before and after activation; source-cap geometry and floor elevations remain exact.','Remove external support from a named frame/cross-rail cycle to prove it cannot ground itself.','Keep the separated parapet base unrooted until a specific authored design is accepted; do not infer a mount from either sampled parent. No epsilon inflation or global adjacency reversal.'],'newLinksApplied':0,'newGroundAnchors':0,'changedGeometry':0,'changedFuelOrCoating':0,'changedPhysicalProfiles':0,'rendererStarted':False,'all1092Adjudicated':False}
if __name__=='__main__':
 parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--check',action='store_true');args=parser.parse_args();proposal=build();payload=json.dumps(proposal,indent=2,sort_keys=True)+'\n';path=HERE/'proposal.json'
 if args.check:assert path.read_text(encoding='utf-8')==payload
 else:path.write_text(payload,encoding='utf-8',newline='\n')
 print(json.dumps({'status':proposal['status'],'localPairs':len(proposal['proposedLocalPairs']),'genuineGapCases':len(proposal['genuineGapCasesHeldForDecision']),'newLinksApplied':0,'geometryChanges':0,'sha256':sha(path)},sort_keys=True))
